/**
 * @file port_can.c
 * @brief Hardware specific implementation of the CAN port layer for STM32H7.
 * Provides modular interface for RX/TX operations with FreeRTOS.
 */
#include <stdio.h>
#include "port_can.h"
#include "FreeRTOS.h"
#include "queue.h"
#include "task.h"
#include "app_can.h"

/* Global extern queue defined in app_can.c */
extern QueueHandle_t s_can_queue;

/* External reference to the FDCAN handle generated by STM32CubeMX.
 * Ensure FDCAN1 is configured for PA11 (RX) and PA12 (TX) in your IOC file.
 */
extern FDCAN_HandleTypeDef hfdcan1;

/**
 * @brief Initialize FDCAN hardware, filters, and start the controller.
 * @return 0 for success, 1 for error.
 */
uint8_t Port_CAN_Init(void)
{
    /* 1. Configure Global Filter BEFORE starting FDCAN to accept all frames */
    if (HAL_FDCAN_ConfigGlobalFilter(&hfdcan1, FDCAN_ACCEPT_IN_RX_FIFO0, FDCAN_ACCEPT_IN_RX_FIFO0, FDCAN_REJECT_REMOTE, FDCAN_REJECT_REMOTE) != HAL_OK) {
        return 1;
    }

    /* 2. Start the FDCAN module */
    if (HAL_FDCAN_Start(&hfdcan1) != HAL_OK) {
        return 1;
    }

    /* 3. Enable Hardware Interrupts for RX FIFO 0 AND Error Statuses */
    uint32_t active_it = FDCAN_IT_RX_FIFO0_NEW_MESSAGE |
                         FDCAN_IT_ERROR_PASSIVE |
                         FDCAN_IT_ERROR_WARNING |
                         FDCAN_IT_BUS_OFF;

    if (HAL_FDCAN_ActivateNotification(&hfdcan1, active_it, 0) != HAL_OK) {
        return 1;
    }

    return 0;
}

/**
 * @brief Transmit a CAN message using TX FIFO safely.
 * @param p_msg Pointer to the message structure.
 * @return 0 for success, 1 for error.
 */
uint8_t Port_CAN_Transmit(const Port_CAN_Msg_t *p_msg)
{
    /* --- FATAL CRASH PREVENTION --- */
    /* Clamp the payload length to a maximum of 8 bytes for Classic CAN */
    uint8_t safe_length = (p_msg->length > 8) ? 8 : p_msg->length;

    FDCAN_TxHeaderTypeDef TxHeader;

    TxHeader.Identifier = p_msg->id;
    TxHeader.IdType = p_msg->is_ext_id ? FDCAN_EXTENDED_ID : FDCAN_STANDARD_ID;
    TxHeader.TxFrameType = FDCAN_DATA_FRAME;
    TxHeader.DataLength = (safe_length << 16);  /* Use safe length to prevent HAL buffer overflow */
    TxHeader.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
    TxHeader.BitRateSwitch = FDCAN_BRS_OFF;
    TxHeader.FDFormat = FDCAN_CLASSIC_CAN;
    TxHeader.TxEventFifoControl = FDCAN_NO_TX_EVENTS;
    TxHeader.MessageMarker = 0;

    if (HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &TxHeader, (uint8_t *)p_msg->data) != HAL_OK)
    {
        return 1;
    }

    return 0;
}

/**
 * @brief Configure hardware filters for specific IDs.
 * @param filter_id Target CAN ID to accept.
 * @param filter_mask Mask for the target ID.
 * @param is_ext_id True for Extended ID, False for Standard ID.
 * @return 0 for success, 1 for error.
 */
uint8_t Port_CAN_SetFilter(uint32_t filter_id, uint32_t filter_mask, bool is_ext_id)
{
    FDCAN_FilterTypeDef sFilterConfig = {0};

    sFilterConfig.IdType = is_ext_id ? FDCAN_EXTENDED_ID : FDCAN_STANDARD_ID;
    sFilterConfig.FilterIndex = 0;
    sFilterConfig.FilterType = FDCAN_FILTER_MASK;
    sFilterConfig.FilterConfig = FDCAN_FILTER_TO_RXFIFO0;
    sFilterConfig.FilterID1 = filter_id;
    sFilterConfig.FilterID2 = filter_mask;

    if (HAL_FDCAN_ConfigFilter(&hfdcan1, &sFilterConfig) != HAL_OK)
    {
        return 1;
    }

    return 0;
}

/**
 * @brief Hardware Interrupt Callback for STM32 FDCAN.
 * @note This overrides the weak function inside the HAL library.
 * It reads the hardware register and safely posts the message via Application API.
 * @param hfdcan Pointer to FDCAN handle.
 * @param RxFifo0ITs Interrupt flags.
 */
void HAL_FDCAN_RxFifo0Callback(FDCAN_HandleTypeDef *hfdcan, uint32_t RxFifo0ITs)
{
    if ((RxFifo0ITs & FDCAN_IT_RX_FIFO0_NEW_MESSAGE) != RESET)
    {
        FDCAN_RxHeaderTypeDef RxHeader;
        Port_CAN_Msg_t rx_msg = {0};
        uint8_t rx_buffer[64] = {0};

        /* Extract message from hardware FIFO into the safe buffer */
        if (HAL_FDCAN_GetRxMessage(hfdcan, FDCAN_RX_FIFO0, &RxHeader, rx_buffer) == HAL_OK)
        {
            rx_msg.id = RxHeader.Identifier;
            rx_msg.is_ext_id = (RxHeader.IdType == FDCAN_EXTENDED_ID) ? true : false;

            /* Bulletproof length extraction */
            if (RxHeader.DataLength <= 64)
            {
                rx_msg.length = RxHeader.DataLength;
            }
            else
            {
                uint8_t dlc_to_bytes[] = {0, 1, 2, 3, 4, 5, 6, 7, 8, 12, 16, 20, 24, 32, 48, 64};
                uint32_t dlc_index = (RxHeader.DataLength >> 16) & 0x0F;
                rx_msg.length = dlc_to_bytes[dlc_index];
            }

            if (rx_msg.length > 8) rx_msg.length = 8;

            /* Copy payload securely */
            for(int i = 0; i < rx_msg.length; i++) {
                rx_msg.data[i] = rx_buffer[i];
            }

            printf("[ISR_CAN] HardWare RX -> ID: 0x%lX, Len: %d\r\n", rx_msg.id, rx_msg.length);

            /* Context variable for FreeRTOS ISR */
            BaseType_t xHigherPriorityTaskWoken = pdFALSE;

            /* >>> CRITICAL FIX: Use the properly wrapped Application API! <<< */
            App_CAN_ISR_Receive(&rx_msg, &xHigherPriorityTaskWoken);

            /* Request context switch if a higher priority task is waiting */
            portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
        }
    }
}

/**
 * @brief Hardware Error Callback for STM32 FDCAN.
 * @note Triggers when a bus error, ACK error, or bus-off event occurs.
 * @param hfdcan Pointer to FDCAN handle.
 * @param ErrorStatusITs Error status interrupt flags.
 */
void HAL_FDCAN_ErrorStatusCallback(FDCAN_HandleTypeDef *hfdcan, uint32_t ErrorStatusITs)
{
    /* Use a breakpoint here or print the error state */
    printf("[FDCAN_ERROR] Hardware Error IT Status: 0x%08lX\r\n", ErrorStatusITs);

    /* Typical Errors:
     * 0x00000001 : FDCAN_IT_ERROR_WARNING
     * 0x00000002 : FDCAN_IT_ERROR_PASSIVE (Usually missing ACK / Baudrate mismatch)
     * 0x00000004 : FDCAN_IT_BUS_OFF (Severely corrupted bus / short circuit)
     */
}

/**
 * @brief Dump FDCAN hardware registers for deep diagnostics.
 */
void Port_CAN_Print_Diagnostics(void)
{
    uint32_t psr = hfdcan1.Instance->PSR;
    uint32_t ecr = hfdcan1.Instance->ECR;
    uint32_t txfqs = hfdcan1.Instance->TXFQS;
    uint32_t rxf0s = hfdcan1.Instance->RXF0S; /* Read RX FIFO status */

    uint8_t lec = psr & 0x07;
    uint8_t act = (psr >> 3) & 0x03;
    uint8_t ep  = (psr >> 5) & 0x01;
    uint8_t bo  = (psr >> 7) & 0x01;

    uint8_t tec = (ecr >> 16) & 0xFF;
    uint8_t rec = (ecr >> 8) & 0x7F;

    /* Parse TX FIFO pointers */
    uint8_t tx_free = txfqs & 0x3F;         /* Free space level */
    uint8_t tx_put  = (txfqs >> 16) & 0x1F; /* Put index */
    uint8_t tx_get  = (txfqs >> 8) & 0x1F;  /* Get index */

    /* Parse RX FIFO 0 pointers */
    uint8_t rx_fill = rxf0s & 0x7F;         /* Number of received packets (Fill Level) */
    uint8_t rx_get  = (rxf0s >> 8) & 0x3F;  /* Get index */

    printf("\r\n=== FDCAN HARDWARE DIAGNOSTICS ===\r\n");
    printf("Status   -> BusOff: %d, ErrorPassive: %d, Activity: %d, LEC: %d\r\n", bo, ep, act, lec);
    printf("Errors   -> TEC: %d, REC: %d\r\n", tec, rec);
    printf("TX FIFO  -> Free: %d, Put: %d, Get: %d\r\n", tx_free, tx_put, tx_get);
    printf("RX FIFO0 -> FillLevel: %d, Get: %d\r\n", rx_fill, rx_get);
    printf("==================================\r\n");
}
